$('#export-progress').onclick=()=>{
 if(!AC?.hasAccount()||!appReady)return;AC.track('progress_export',{count:Object.keys(store.answers).length});
 const blob=new Blob([JSON.stringify({...store,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download='EC2K2-study-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress backup downloaded');
};
$('#import-progress').onchange=async event=>{
 const ctx=accountAccess();
 try{
  if(!ctx.hasAccount||!appReady)return;const file=event.target.files[0];if(!file)return;if(file.size>8000000)throw Error('Backup is too large');
  const value=JSON.parse(await file.text());if(!accessMatches(ctx)||!appReady)return;
  if(value.version!==2||!value.answers||typeof value.answers!=='object'||!Array.isArray(value.bookmarks)||!Array.isArray(value.understood))throw Error('Not an EC2K2 progress backup');
  store=cleanProgress(value);AC.track('progress_import',{count:Object.keys(store.answers).length});save();render(false);toast('Study progress imported');
 }catch(error){if(accessMatches(ctx))toast('Import failed. '+error.message)}finally{event.target.value=''}
};
AC=createAccountSync({getStore:()=>store,useStore:(key,state)=>{KEY=key;store=cleanForAccount(state);save();render(false)},clean:cleanForAccount,render,toast,guestKey:GUEST_KEY,deferSync:true});
